import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div className="component-preview relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout">
      {children}
    </div>
  );
}

import { useRef } from "react";
import { shake } from "@/registry/erbium/lib/shake";
import { Button } from "@/registry/erbium/ui/button";
export default function Demo() {
  const ref = useRef<HTMLButtonElement>(null);
  return (
    <Button ref={ref} variant="error" onClick={() => shake(ref.current)}>
      Replay error feedback
    </Button>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/shake-demo\";\n\nconst Example = () => <Demo />;\n\nexport default Example;\n";

const meta = {
  title: "UI/Shake",
  parameters: {
    layout: "centered",
    docs: { description: { component: "Replays error feedback on an element without changing its validation state. The animation respects the reduced motion preference and RTL direction.\n\nImport `shake` from `@/registry/erbium/lib/shake` and call it with an element ref." } },
  },
} satisfies Meta;

export default { ...meta,  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

import Demo from "../examples/shake-demo";

const Example = () => <Demo />;

export default Example;
